package br.com.sysanimais.api

import com.fasterxml.jackson.databind.ObjectMapper
import org.junit.jupiter.api.Test
import org.junit.jupiter.api.BeforeEach
import org.junit.jupiter.api.Assertions.*
import org.springframework.beans.factory.annotation.Autowired
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc
import org.springframework.boot.test.context.SpringBootTest
import org.springframework.http.MediaType
import org.springframework.jdbc.core.JdbcTemplate
import org.springframework.security.oauth2.jwt.*
import org.springframework.security.oauth2.jose.jws.MacAlgorithm
import org.springframework.test.context.TestPropertySource
import org.springframework.test.web.servlet.*
import org.springframework.transaction.annotation.Transactional
import java.time.Instant

@SpringBootTest @AutoConfigureMockMvc @Transactional
@TestPropertySource(properties=["spring.datasource.url=jdbc:h2:mem:adocoes;MODE=MySQL;DB_CLOSE_DELAY=-1;DATABASE_TO_LOWER=TRUE","spring.datasource.driver-class-name=org.h2.Driver","spring.datasource.username=sa","spring.datasource.password=","app.jwt-secret=0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef"])
class AdocaoApiTests @Autowired constructor(val mvc:MockMvc,val db:JdbcTemplate,val json:ObjectMapper,val jwt:JwtEncoder) {
 @jakarta.persistence.PersistenceContext lateinit var em:jakarta.persistence.EntityManager
 @BeforeEach fun fixtures() {
  db.update("INSERT INTO ong(id,nome,email) VALUES(501,'ONG A','a@adocao.invalid'),(502,'ONG B','b@adocao.invalid')")
  for((id,ong,perfil) in listOf(Triple(501,501,"administrador"),Triple(502,502,"administrador"),Triple(503,null,"usuario"),Triple(504,null,"usuario"),Triple(505,501,"voluntario"),Triple(506,501,"veterinario"),Triple(507,null,"admin_plataforma")))
   db.update("INSERT INTO usuario(id,ong_id,nome,email,senha_hash,perfil,ativo) VALUES(?,?,?,?,?,?,true)",id,ong,"Pessoa $id","u$id@adocao.invalid","x",perfil)
  for((id,ong) in listOf(501 to 501,502 to 502)) db.update("INSERT INTO animal(id,ong_id,nome,especie,sexo,porte,data_entrada,situacao,situacao_atualizada_em,situacao_alterada_por,ativo,publicado,criado_em,atualizado_em,versao) VALUES(?,?,'Luna','CAO','FEMEA','MEDIO',CURRENT_DATE,'DISPONIVEL',CURRENT_TIMESTAMP,501,true,true,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,0)",id,ong)
 }
 private fun auth(id:Int):String {val now=Instant.now();return "Bearer "+jwt.encode(JwtEncoderParameters.from(JwsHeader.with(MacAlgorithm.HS256).build(),JwtClaimsSet.builder().subject(id.toString()).issuedAt(now).expiresAt(now.plusSeconds(3600)).build())).tokenValue}
 private fun create(user:Int=503,animal:Int=501):Long {val r=mvc.post("/api/adoption-requests"){header("Authorization",auth(user));contentType=MediaType.APPLICATION_JSON;content="""{"animalId":$animal,"mensagem":"Gostaria de conhecer"}"""}.andExpect{status{isCreated()};jsonPath("$.status"){value("PENDENTE")}}.andReturn();return json.readTree(r.response.contentAsString)["id"].asLong()}
 private fun patch(id:Long,action:String,user:Int=501,body:String?=null)=mvc.patch("/api/ong/adoption-requests/$id/$action"){header("Authorization",auth(user));if(body!=null){contentType=MediaType.APPLICATION_JSON;content=body}}
 private fun delivery(id:Long,body:String="""{"entregaConfirmada":true}""")=mvc.post("/api/ong/adoption-requests/$id/confirmar-entrega"){header("Authorization",auth(501));contentType=MediaType.APPLICATION_JSON;content=body}
 private fun state()=db.queryForObject("SELECT situacao FROM animal WHERE id=501",String::class.java)
 @Test fun `criacao propria e duplicidade pendente`() {val id=create();create(504);mvc.get("/api/me/adoption-requests"){header("Authorization",auth(503))}.andExpect{status{isOk()};jsonPath("$.totalElements"){value(1)}};mvc.get("/api/me/adoption-requests/$id"){header("Authorization",auth(504))}.andExpect{status{isNotFound()}};mvc.post("/api/adoption-requests"){header("Authorization",auth(503));contentType=MediaType.APPLICATION_JSON;content="""{"animalId":501}"""}.andExpect{status{isConflict()}};assertEquals("DISPONIVEL",state())}
 @Test fun `animal inelegivel e ausente`() {db.update("UPDATE animal SET publicado=false WHERE id=501");mvc.post("/api/adoption-requests"){header("Authorization",auth(503));contentType=MediaType.APPLICATION_JSON;content="""{"animalId":501}"""}.andExpect{status{isConflict()}};mvc.post("/api/adoption-requests"){header("Authorization",auth(503));contentType=MediaType.APPLICATION_JSON;content="""{"animalId":99999}"""}.andExpect{status{isNotFound()}}}
 @Test fun `campos arbitrarios e acesso anonimo sao recusados`() {mvc.post("/api/adoption-requests"){contentType=MediaType.APPLICATION_JSON;content="""{"animalId":501}"""}.andExpect{status{isUnauthorized()}};mvc.post("/api/adoption-requests"){header("Authorization",auth(503));contentType=MediaType.APPLICATION_JSON;content="""{"animalId":501,"usuarioId":504}"""}.andExpect{status{isBadRequest()}}}
 @Test fun `aprovacao reserva sem encerrar concorrentes`() {val a=create();val b=create(504);patch(a,"aprovar",505).andExpect{status{isOk()};jsonPath("$.status"){value("APROVADA")}};assertEquals("EM_PROCESSO_ADOCAO",state());patch(b,"aprovar").andExpect{status{isConflict()}};patch(a,"aprovar").andExpect{status{isConflict()}};assertEquals("PENDENTE",db.queryForObject("SELECT status FROM solicitacao_adocao WHERE id=?",String::class.java,b))}
 @Test fun `isolamento institucional e perfis`() {val a=create();for(user in listOf(503,506,507)){mvc.get("/api/ong/adoption-requests"){header("Authorization",auth(user))}.andExpect{status{isForbidden()}};patch(a,"aprovar",user).andExpect{status{isForbidden()}}};mvc.get("/api/ong/adoption-requests/$a"){header("Authorization",auth(502))}.andExpect{status{isNotFound()}};patch(a,"aprovar",502).andExpect{status{isNotFound()}}}
 @Test fun `rejeicao exige justificativa`() {val a=create();patch(a,"rejeitar",body="""{"justificativa":" "}""").andExpect{status{isBadRequest()}};patch(a,"rejeitar",body="""{"justificativa":"Condições incompatíveis"}""").andExpect{status{isOk()};jsonPath("$.status"){value("REJEITADA")};jsonPath("$.analisadoEm"){exists()}};assertEquals("DISPONIVEL",state())}
 @Test fun `solicitante cancela pendente e aprovado`() {val a=create();mvc.patch("/api/me/adoption-requests/$a/cancelar"){header("Authorization",auth(504))}.andExpect{status{isNotFound()}};patch(a,"aprovar").andExpect{status{isOk()}};mvc.patch("/api/me/adoption-requests/$a/cancelar"){header("Authorization",auth(503))}.andExpect{status{isOk()};jsonPath("$.status"){value("CANCELADA")}};assertEquals("DISPONIVEL",state());val b=create();mvc.patch("/api/me/adoption-requests/$b/cancelar"){header("Authorization",auth(503))}.andExpect{status{isOk()}}}
 @Test fun `cancelamento administrativo libera reserva e preserva historico`() {val a=create();val b=create(504);patch(a,"aprovar").andExpect{status{isOk()}};patch(a,"cancelar-aprovacao",body="""{"justificativa":"Desistência"}""").andExpect{status{isOk()};jsonPath("$.analisadoEm"){exists()};jsonPath("$.canceladoEm"){exists()}};assertEquals("DISPONIVEL",state());patch(b,"aprovar").andExpect{status{isOk()}};assertEquals(3,db.queryForObject("SELECT COUNT(*) FROM historico_adocao WHERE solicitacao_id=?",Int::class.java,a))}
 @Test fun `entrega exige confirmacao e conclui uma unica adocao`() {val a=create();val b=create(504);delivery(a).andExpect{status{isConflict()}};patch(a,"aprovar").andExpect{status{isOk()}};delivery(a,"""{"entregaConfirmada":false}""").andExpect{status{isBadRequest()}};delivery(a).andExpect{status{isOk()};jsonPath("$.status"){value("CONCLUIDA")};jsonPath("$.adocao.dataEntrega"){exists()}};assertEquals("ADOTADO",state());assertEquals("REJEITADA",db.queryForObject("SELECT status FROM solicitacao_adocao WHERE id=?",String::class.java,b));delivery(a).andExpect{status{isConflict()}};assertEquals(1,db.queryForObject("SELECT COUNT(*) FROM adocao",Int::class.java))}
 @Test fun `ong suspensa e conta desativada bloqueiam aprovacao`() {val a=create();db.update("UPDATE ong SET situacao='SUSPENSA' WHERE id=501");em.clear();patch(a,"aprovar").andExpect{status{isForbidden()}};db.update("UPDATE ong SET situacao='ATIVA' WHERE id=501");db.update("UPDATE usuario SET ativo=false WHERE id=501");em.clear();patch(a,"aprovar").andExpect{status{isForbidden()}}}
 @Test fun `reserva nao pode ser desfeita por situacao manual ou inativacao`() {val a=create();patch(a,"aprovar").andExpect{status{isOk()}};val version=db.queryForObject("SELECT versao FROM animal WHERE id=501",Long::class.java);mvc.patch("/api/ong/animais/501/situacao"){header("Authorization",auth(501));contentType=MediaType.APPLICATION_JSON;content="""{"situacao":"DISPONIVEL","versao":$version}"""}.andExpect{status{isConflict()}};mvc.patch("/api/ong/animais/501/inativacao"){header("Authorization",auth(501))}.andExpect{status{isConflict()}};assertEquals("EM_PROCESSO_ADOCAO",state())}
 @Test fun `funcionarios e perfil global nao criam solicitacao publica`() {for(user in listOf(501,505,506,507)) mvc.post("/api/adoption-requests"){header("Authorization",auth(user));contentType=MediaType.APPLICATION_JSON;content="""{"animalId":501}"""}.andExpect{status{isForbidden()}}}
 @Test fun `cancelamento antigo nao libera reserva de outro solicitante`() {val a=create();val b=create(504);patch(a,"aprovar").andExpect{status{isOk()}};patch(a,"cancelar-aprovacao",body="""{"justificativa":"Desistência"}""").andExpect{status{isOk()}};patch(b,"aprovar").andExpect{status{isOk()}};mvc.patch("/api/me/adoption-requests/$a/cancelar"){header("Authorization",auth(503))}.andExpect{status{isConflict()}};assertEquals("EM_PROCESSO_ADOCAO",state())}
 @Test fun `lista institucional filtra e pagina pedidos da propria ong`() {val a=create();create(504);create(503,502);patch(a,"aprovar").andExpect{status{isOk()}};mvc.get("/api/ong/adoption-requests?status=APROVADA&animalId=501&size=1"){header("Authorization",auth(505))}.andExpect{status{isOk()};jsonPath("$.totalElements"){value(1)};jsonPath("$.content[0].solicitante.email"){exists()}};mvc.get("/api/ong/adoption-requests?page=1&size=1"){header("Authorization",auth(501))}.andExpect{status{isOk()};jsonPath("$.totalElements"){value(2)}};mvc.get("/api/ong/adoption-requests?size=101"){header("Authorization",auth(501))}.andExpect{status{isBadRequest()}}}

}
